<?php require_once __DIR__.'/../includes/security.php';require __DIR__.'/../includes/db.php';$token=$_GET['token']??$_POST['token']??'';$error='';$done=false;if(!preg_match('/^[a-f0-9]{64}$/',$token)){$error='Token tidak valid.';}else{$hash=hash('sha256',$token);$q=$pdo->prepare('SELECT id,admin_id FROM admin_password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() ORDER BY id DESC LIMIT 1');$q->execute([$hash]);$reset=$q->fetch();if(!$reset)$error='Token tidak valid atau sudah kedaluwarsa.';elseif($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pw=$_POST['password']??'';if(strlen($pw)<12||strlen($pw)>200)$error='Kata sandi minimal 12 karakter.';else{$pdo->beginTransaction();$pdo->prepare('UPDATE admin_users SET password_hash=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$reset['admin_id']]);$pdo->prepare('UPDATE admin_password_resets SET used_at=NOW() WHERE admin_id=? AND used_at IS NULL')->execute([$reset['admin_id']]);$pdo->commit();$done=true;}}} ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atur ulang kata sandi admin</title><link rel="stylesheet" href="../assets/style.css"></head><body><form class="panel adminlogin" method="post"><h1>Atur ulang kata sandi</h1><?php if($done):?><div class="notice">Kata sandi diperbarui. <a href="login.php">Masuk</a></div><?php else:?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="token" value="<?=e($token)?>"><div class="field"><label>Kata sandi baru (minimal 12 karakter)</label><input type="password" name="password" minlength="12" maxlength="200" required></div><button class="btn full">Simpan kata sandi</button><?php endif?></form></body></html>